// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;

    function setUp() public { c = new Synth(address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(address spender, uint256 startAllowance, uint256 subtractedValue) public {
        vm.assume(spender != address(0));
        vm.assume(spender != address(c));

        // The caller (this test contract) is its own owner.
        address owner = address(this);

        // Normalize to a WIDE but admissible domain: allowance and subtraction both within the
        // representable range, with the subtraction not exceeding the allowance (so the
        // reference must succeed: currentAllowance >= subtractedValue).
        startAllowance = bound(startAllowance, 0, type(uint256).max - 1);
        subtractedValue = bound(subtractedValue, 0, startAllowance);

        // Approve the spender for startAllowance and then decrease by subtractedValue.
        // Both calls originate from the test contract, the actual owner of its own allowance.
        bool approveOk = c.approve(spender, startAllowance);
        assertTrue(approveOk, "approve unexpectedly failed");

        // Reference C: succeeds whenever subtractedValue <= startAllowance.
        // Mutant M: reverts when subtractedValue == startAllowance (equal to currentAllowance).
        // A fuzzed address that is non-zero and distinct from c is enough: no external
        // counterparty is needed because decreaseAllowance is purely internal bookkeeping.
        bool decreaseOk;
        try c.decreaseAllowance(spender, subtractedValue) {
            decreaseOk = true;
        } catch {
            decreaseOk = false;
        }

        // GENERAL RULE: for every admissible input the reference satisfies `decreaseOk == true`
        // AND afterwards the allowance is exactly the old allowance minus subtractedValue.
        // The mutant breaks this for some input (the fuzzer will find e.g. subtractedValue == startAllowance).
        uint256 remaining = c.allowance(owner, spender);
        assertTrue(decreaseOk, "decreaseAllowance must not revert when subtractedValue <= currentAllowance");
        assertTrue(remaining == startAllowance - subtractedValue, "allowance must be reduced by exactly subtractedValue");
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
